const skipButton = { inline_keyboard: [[{ text: msg.skip, callback_data: 'skip' }]] };

const input = $input.first().json;
const callbackQuery = input.callback_query;
const message = callbackQuery ? callbackQuery.message : input.message;
const text = callbackQuery ? callbackQuery.data : (input.message?.text || input.message?.caption || '');
const chatId = callbackQuery ? callbackQuery.message.chat.id : input.message.chat.id;
const staticData = $getWorkflowStaticData('global');

if (callbackQuery) {
  await answerCallback(callbackQuery.id);
}

// Clean up stale state (1 hour TTL)
if (staticData[chatId]?.ts && Date.now() - staticData[chatId].ts > 3600000) {
  delete staticData[chatId];
}

if (text === '/start') {
  const prompts = await nocoGet('/tables/{{NOCODB_PROMPTS_TABLE_ID}}/records?limit=1&fields=Id');
  if (prompts.list && prompts.list[0]) {
    await nocoPatch('/tables/{{NOCODB_PROMPTS_TABLE_ID}}/records', { Id: prompts.list[0].Id, TelegramChatId: String(chatId) });
  }
  await sendTelegram(chatId, msg.connected);
} else if (!callbackQuery && (input.message?.forward_date || input.message?.forward_origin)) {
  // Forwarded message -> becomes Description, ask for Topic (with Skip)
  const mgId = input.message?.media_group_id;
  // Telegram album: each photo arrives as its own webhook with the same
  // media_group_id. Only the captioned photo carries text; siblings are empty.
  // Race-safe filter: ignore siblings without text. (staticData dedup races when
  // parallel executions all read the snapshot before any of them writes back.)
  if (mgId && !text) {
    return [{ json: { success: true, skipped: 'media_group_sibling' } }];
  }
  if (mgId) {
    const mgKey = '_mg_' + chatId;
    if (staticData[mgKey] === mgId) {
      return [{ json: { success: true, skipped: 'media_group_dup' } }];
    }
    staticData[mgKey] = mgId;
  }
  staticData[chatId] = { step: 'awaiting_topic', description: text, ts: Date.now() };
  await sendTelegram(chatId, msg.gotIt, skipButton);
} else if (staticData[chatId]?.step === 'awaiting_topic') {
  const topic = text === 'skip' ? '' : text;
  staticData[chatId].step = 'awaiting_article_url';
  staticData[chatId].topic = topic;
  staticData[chatId].ts = Date.now();
  const articleUrlButtons = { inline_keyboard: [
    [{ text: msg.latestArticle, callback_data: 'latest' }],
    [{ text: msg.skip, callback_data: 'skip' }]
  ] };
  await sendTelegram(chatId, msg.sendArticleUrl, articleUrlButtons);
} else if (staticData[chatId]?.step === 'awaiting_description') {
  // After topic-first entry: user sends description or skips
  const description = text === 'skip' ? '' : text;
  staticData[chatId].description = description;
  staticData[chatId].step = 'awaiting_article_url';
  staticData[chatId].ts = Date.now();
  const articleUrlButtons = { inline_keyboard: [
    [{ text: msg.latestArticle, callback_data: 'latest' }],
    [{ text: msg.skip, callback_data: 'skip' }]
  ] };
  await sendTelegram(chatId, msg.descriptionSaved, articleUrlButtons);
} else if (staticData[chatId]?.step === 'awaiting_article_url') {
  staticData[chatId].articleUrl = text === 'skip' ? '' : (text === 'latest' ? 'latest' : text);
  staticData[chatId].ts = Date.now();
  if (staticData[chatId].articleUrl) {
    staticData[chatId].step = 'awaiting_board';
    await sendTelegram(chatId, msg.sendBoard, skipButton);
  } else {
    staticData[chatId].step = 'awaiting_link';
    await sendTelegram(chatId, msg.topicSaved, skipButton);
  }
} else if (staticData[chatId]?.step === 'awaiting_link') {
  staticData[chatId].step = 'awaiting_board';
  staticData[chatId].link = text === 'skip' ? '' : text;
  staticData[chatId].ts = Date.now();
  await sendTelegram(chatId, msg.sendBoard, skipButton);
} else if (staticData[chatId]?.step === 'awaiting_board') {
  const topic = staticData[chatId].topic || '';
  const description = staticData[chatId].description || '';
  const link = staticData[chatId].link;
  const articleUrl = staticData[chatId].articleUrl;
  const board = text === 'skip' ? '' : text;
  delete staticData[chatId];
  const record = {};
  if (topic) record.Topic = topic;
  if (description) record.Description = description;
  if (link) record.Link = link;
  if (articleUrl) record.ArticleURL = articleUrl;
  if (board) record.Board = board;
  if (Object.keys(record).length === 0) {
    await sendTelegram(chatId, msg.emptyRecord);
    return [{ json: { success: true, skipped: 'empty_record' } }];
  }
  try {
    await nocoPost('/tables/{{NOCODB_TABLE_ID}}/records', record);
    let summary = msg.added;
    if (topic) summary += '\n' + msg.topic + ': ' + topic;
    if (description) summary += '\n' + msg.description + ': ' + description.slice(0, 100);
    await sendTelegram(chatId, summary);
  } catch (e) {
    await sendTelegram(chatId, msg.errorSaving);
  }
} else if (!callbackQuery && !staticData[chatId]) {
  // Regular message (not forwarded, no active state) -> treat as Topic, ask for Description
  staticData[chatId] = { step: 'awaiting_description', topic: text, ts: Date.now() };
  await sendTelegram(chatId, msg.sendDescription, skipButton);
} else {
  await sendTelegram(chatId, msg.help);
}

return [{ json: { success: true } }];
